module fir30_v5_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:29];
    integer     i;
    reg  [23:0] acc;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 30; i = i + 1) xs[i] <= 8'd0;
            acc <= 24'd0;
            y <= 16'd0;
        end else begin
            acc <= 24'd0;
            acc <= acc + xs[0] * 8'd44;
            acc <= acc + xs[1] * 8'd37;
            acc <= acc + xs[2] * 8'd25;
            acc <= acc + xs[3] * 8'd24;
            acc <= acc + xs[4] * 8'd58;
            acc <= acc + xs[5] * 8'd4;
            acc <= acc + xs[6] * 8'd24;
            acc <= acc + xs[7] * 8'd58;
            acc <= acc + xs[8] * 8'd23;
            acc <= acc + xs[9] * 8'd46;
            acc <= acc + xs[10] * 8'd25;
            acc <= acc + xs[11] * 8'd35;
            acc <= acc + xs[12] * 8'd40;
            acc <= acc + xs[13] * 8'd8;
            acc <= acc + xs[14] * 8'd33;
            acc <= acc + xs[15] * 8'd12;
            acc <= acc + xs[16] * 8'd18;
            acc <= acc + xs[17] * 8'd9;
            acc <= acc + xs[18] * 8'd63;
            acc <= acc + xs[19] * 8'd4;
            acc <= acc + xs[20] * 8'd1;
            acc <= acc + xs[21] * 8'd45;
            acc <= acc + xs[22] * 8'd21;
            acc <= acc + xs[23] * 8'd43;
            acc <= acc + xs[24] * 8'd25;
            acc <= acc + xs[25] * 8'd33;
            acc <= acc + xs[26] + xs[27]*8'd4;
            acc <= acc + xs[28] * 8'd57;
            acc <= acc + xs[29] * 8'd44;
            y <= acc[15:0];
            xs[0] <= x;
            for (i = 1; i < 30; i = i + 1) xs[i] <= xs[i-1];
        end
    end
endmodule

